### Quick “drop‑in” replacement for the JWT secret in the existing codebase

Create **`secrets.js`** (AWS Secrets Manager example, but you can swap the implementation later):

```js
// secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });

let cache = {};

async function getJwtSecret() {
  const secretName = process.env.JWT_SECRET_NAME || 'my-app-prod'; // name of the secret in AWS
  if (cache.jwt) return cache.jwt;

  const cmd = new GetSecretValueCommand({ SecretId: secretName });
  const { SecretString } = await client.send(cmd);
  const parsed = JSON.parse(SecretString);
  cache.jwt = parsed.JWT_SECRET;
  return cache.jwt;
}

module.exports = { getJwtSecret };
```

Update **`auth.js`** to load it asynchronously once (or cache it):

```js
// auth.js
const jwt = require('jsonwebtoken');
const { getJwtSecret } = require('./secrets');

let jwtSecret;   // will be resolved at first request
async function loadSecret() {
  if (!jwtSecret) {
    jwtSecret = await getJwtSecret();
    if (!jwtSecret) throw new Error('JWT secret could not be loaded');
  }
}
async function authenticate(req, res, next) {
  await loadSecret();
  const authHeader = req.headers.authorization;
  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing token' });
