## 4️⃣ Best‑practice way to handle secrets  

Below is a **complete, production‑ready pattern** that:

1. **Never** loads a raw `.env` file in production.  
2. Falls back to **dotenv** **only** for local development / test runs.  
3. Uses **AWS Secrets Manager** (as an example) for real secrets.  
4. Wraps the secret‑fetch with a tiny helper that caches the value and fails fast if the secret cannot be retrieved.

> *(If you use another cloud provider, replace the AWS SDK calls with the equivalent SDK – the pattern stays the same.)*

```js
// config.js  – Centralised configuration & secret loading
/* -------------------------------------------------------
   1️⃣  Load .env only when NODE_ENV !== 'production'
   2️⃣  Pull production secrets from AWS Secrets Manager
   3️⃣  Export a single immutable config object.
   ------------------------------------------------------- */

const fs = require('fs');
const path = require('path');

if (process.env.NODE_ENV !== 'production') {
  // Development / test – load .env (or .env.test) for convenience
  const dotenv = require('dotenv');
  const envFile = process.env.NODE_ENV === 'test' ? '.env.test' : '.env';
  if (fs.existsSync(envFile)) {
    dotenv.config({ path: envFile });
    console.log(`[config] Loaded environment variables from ${envFile}`);
  } else {
    console.warn(`[config] No ${envFile} found – proceeding with existing env`);
  }
}

/* -------------------------------------------------------
   4️⃣  Helper to fetch a secret from AWS Secrets Manager.
       The secret is cached in memory for the life of the
       process (good for most serverless / container apps).
   ------------------------------------------------------- */
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const secretCache = new Map();

async function getAwsSecret(secretName) {
  if (secretCache.has(secretName)) {
    return secretCache.get(secretName);
  }

  const client = new SecretsManagerClient({
    // The SDK will automatically pick up AWS credentials from the
    // environment (IAM role, ECS task role, etc.) – no hard‑coded keys.
    region: process.env.AWS_REGION || 'us-east-1',
  });

  const cmd = new GetSecretValueCommand({ SecretId: secretName });
  const response = await client.send(cmd);

  const secretString = response.SecretString;
  if (!secretString) {
    throw new Error(`Secret ${secretName} has no string value`);
  }

  const parsed = JSON.parse(secretString); // Store secrets as JSON in SM
  secretCache.set(secretName, parsed);
  return parsed;
}

/* -------------------------------------------------------
   5️⃣  Build the final config object.
   ------------------------------------------------------- */
const config = {
  // Generic runtime config ------------------------------------------------
  port: process.env.PORT ?? 3000,
  nodeEnv: process.env.NODE_ENV ?? 'development',

  // Development‑only values (fallback to env vars) ------------------------
  databaseUrl: process.env.DATABASE_URL,
  stripeKey: process.env.STRIPE_SECRET_KEY,
  anthropicKey: process.env.ANTHROPIC_API_KEY,
  logfireToken: process.env.LOGFIRE_TOKEN,

  // Production‑only secret fetchers (lazy async) -------------------------
  // Example usage:  const { dbUrl } = await config.getSecrets();
  async getSecrets() {
    // Pull a single secret that contains a JSON payload:
    //   { "DATABASE_URL":"postgres://…", "STRIPE_SECRET_KEY":"sk_live…", … }
    const secret = await getAwsSecret('my-app/production');
    return {
      databaseUrl: secret.DATABASE_URL,
      stripeKey: secret.STRIPE_SECRET_KEY,
      anthropicKey: secret.ANTHROPIC_API_KEY,
      logfireToken: secret.LOGFIRE_TOKEN,
    };
  },
};

module.exports = config;
```

