require('dotenv').config();               // <-- load .env (never commit secrets)
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const jwt = require('jsonwebtoken');
const { body, param, validationResult } = require('express-validator');

const app = express();

// ---------- Middleware ----------
app.use(helmet());                         // Security headers (CSP, HSTS, etc.)
app.use(cors({                              // Restrict origins – adjust to your domain
  origin: process.env.CORS_ORIGIN?.split(',') || [],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
}));
app.use(express.json());                  // Body parser for JSON payloads
app.use(morgan('combined'));               // Production‑grade request logging

// Rate limiter – 100 req/min per IP (tune to your traffic)
const apiLimiter = rateLimit({
  windowMs: 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/api/', apiLimiter); // apply to all future API routes

// ---------- Helper – Auth middleware ----------
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer <token>
  if (!token) return res.sendStatus(401); // No token

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) return res.sendStatus(403); // Invalid token
    req.user = user;
    next();
  });
}

// ---------- Sample public endpoint ----------
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    env: process.env.NODE_ENV || 'development',
  });
});

// ---------- Protected /users endpoint ----------
/**
 * Returns user list – **only for authenticated callers**.
 * In a real app this would be fetched from a DB with proper RBAC.
 */
app.get('/users', authenticateToken, (req, res) => {
  // Example static data – never expose raw emails in production without consent
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // OPTIONAL: filter fields based on caller’s role
  const safeUsers = users.map(u => ({
    id: u.id,
    name: u.name,
    // Only expose email to admins:
    ...(req.user.role === 'admin' && { email: u.email }),
  }));

  res.json(safeUsers);
});

// ---------- Example login route (creates JWT) ----------
app.post(
  '/login',
  [
    body('username').isString().trim().escape(),
    body('password').isString(),
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const { username, password } = req.body;

    // TODO: Replace with real user lookup & hashed‑password check (bcrypt)
    if (username === 'admin' && password === 'changeMeNow') {
      const payload = { sub: 1, username, role: 'admin' };
      const token = jwt.sign(payload, process.env.JWT_SECRET, {
        expiresIn: '1h',
      });
      return res.json({ token });
    }

    // Generic auth failure (do not reveal which field was incorrect)
    res.status(401).json({ message: 'Invalid credentials' });
  }
);

// ---------- Global error handler (no stack traces in prod) ----------
app.use((err, req, res, next) => {
  console.error(err); // still log internally
  const status = err.status || 500;
  const response = {
    message: status === 500 ? 'Internal Server Error' : err.message,
  };
  if (process.env.NODE_ENV !== 'production') {
    response.stack = err.stack; // helpful for dev only
  }
  res.status(status).json(response);
});

// ---------- Server start ----------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

