const helmet = require('helmet');               // Security headers
const rateLimit = require('express-rate-limit'); // DoS protection
const cors = require('cors');                  // Controlled cross‑origin requests
const morgan = require('morgan');              // Request logging
const { body, param, query, validationResult } = require('express-validator'); // Input validation
require('dotenv').config(); // Load .env (port, secrets, etc.)

const app = express();

/* ==== Middleware ==== */
// Hide X‑Powered‑By header (default in Express 5, set manually for older versions)
app.disable('x-powered-by');

// Helmet adds a comprehensive set of security headers (CSP, HSTS, etc.)
app.use(helmet());

// Enable CORS only for trusted origins (adjust as needed)
app.use(
  cors({
    origin: process.env.CORS_ORIGIN?.split(',') || [], // e.g. "https://myapp.example.com"
