```

This ensures you *don’t* accidentally run production with a missing secret, while still keeping production secrets out of the repo.

#### b) **AWS Secrets Manager** example (Node SDK v3)

```bash
npm install @aws-sdk/client-secrets-manager
```

```js
// secrets.js – tiny wrapper
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const client = new SecretsManagerClient({ region: process.env.AWS_REGION });

/**
 * Retrieve a secret string from AWS Secrets Manager.
 * The secret must be stored as a JSON object, e.g.
 * {
 *   "DATABASE_URL": "...",
 *   "STRIPE_SECRET_KEY": "..."
 * }
 */
async function loadSecrets(secretName) {
  const cmd = new GetSecretValueCommand({ SecretId: secretName });
  const resp = await client.send(cmd);
  if (!resp.SecretString) throw new Error('Secret has no string value');
  const secrets = JSON.parse(resp.SecretString);

  // Populate process.env only for the keys we care about
  for (const [k, v] of Object.entries(secrets)) {
    if (!process.env[k]) process.env[k] = v;
  }
}

module.exports = { loadSecrets };
```

Usage in `app.js` (early, before any code that needs the values):

```js
if (process.env.NODE_ENV === 'production') {
  const { loadSecrets } = require('./secrets');
  // The secret name can be a env var set by the orchestrator (no hard‑code)
  const secretName = process.env.AWS_SECRETS_NAME; // e.g. "myapp/prod"
  loadSecrets(secretName)
    .then(() => console.log('✅ Secrets loaded from AWS Secrets Manager'))
    .catch(err => {
      console.error('❌ Failed to load secrets:', err);
      process.exit(1);
    });
}
```

> The **IAM role** attached to the compute instance (ECS task, EC2, Lambda, etc.) should have the `secretsmanager:GetSecretValue` permission for the secret name. No static keys live in the repo.

#### c) **Google Secret Manager** example

```bash
npm install @google-cloud/secret-manager
```

```js
// googleSecrets.js
const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');
const client = new SecretManagerServiceClient();

async function loadGoogleSecret(secretId, version = 'latest') {
  const [accessResponse] = await client.accessSecretVersion({
    name: `projects/${process.env.GCP_PROJECT_ID}/secrets/${secretId}/versions/${version}`,
  });
  const payload = accessResponse.payload.data.toString('utf8');
  // Assuming the secret payload is a JSON object with key/value pairs
  const secrets = JSON.parse(payload);
  Object.assign(process.env, secrets); // merges into process.env
}
module.exports = { loadGoogleSecret };
```

In production:

