require('dotenv-safe').config({   // only runs when NODE_ENV !== 'production'
  example: '.env.example',
  allowEmptyValues: false,
});

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');

const app = express();
app.disable('x-powered-by');
app.use(helmet());
app.use(cors({ origin: process.env.CORS_ORIGIN?.split(',') || [] }));
app.use(morgan('combined'));
app.use(express.json());

/* ----- Load secrets from secret manager (only in production) ----- */
if (process.env.NODE_ENV === 'production') {
  // Example: AWS Secrets Manager
  const { loadSecrets } = require('./secrets'); // see AWS example above
  loadSecrets(process.env.AWS_SECRETS_NAME).catch(err => {
    console.error('❌ Unable to fetch secrets from manager', err);
    process.exit(1);
  });
}

/* ----- Routes (same as hard‑enforced version previously shown) ----- */
app.get('/health', (req, res) => {
  // Optionally protect with a secret header token
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/* protected users endpoint */
const authenticate = require('./auth-middleware'); // simple token/JWT check
app.get('/api/users', authenticate, (req, res) => {
