// app.js – Hardened version
require('dotenv').config();               // loads .env (keep secret keys out of repo)

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const pino = require('pino');
const pinoHttp = require('pino-http');

const apiKeyGuard = require('./auth');    // <-- see auth.js below

const app = express();

// ---------- Security & Observability Middleware ----------
app.use(helmet());

// Restrict origins in production (set CORS_ORIGIN env var)
app.use(cors({ origin: process.env.CORS_ORIGIN || '*' }));

app.use(express.json());                  // parse JSON bodies
app.use(morgan('combined'));              // basic request logging

// Structured logging (optional but recommended)
const logger = pino({ level: process.env.LOG_LEVEL || 'info' });
app.use(pinoHttp({ logger }));

// Rate limiting – adjust to your traffic profile
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, try again later.' },
});
app.use(limiter);

// Enforce HTTPS in production (when behind a proxy)
if (process.env.NODE_ENV === 'production') {
  app.enable('trust proxy');
  app.use((req, res, next) => {
    if (req.secure) return next();
    res.redirect(`https://${req.headers.host}${req.originalUrl}`);
  });
}

// ---------- Routes ----------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Protected endpoint – requires a valid API key
app.get('/users', apiKeyGuard, (req, res) => {
  // Never expose raw email addresses unless caller is trusted.
  res.json([
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ]);
});

// ---------- Central Error Handler ----------
app.use((err, req, res, next) => {
  req.log?.error(err);                // pino-http attaches logger to req
  const status = err.status || 500;
  res.status(status).json({ error: err.message || 'Internal Server Error' });
});

// ---------- Server bootstrap ----------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

