### 2️⃣ Add Authentication & Authorization

A quick, production‑ready choice is **JSON Web Tokens (JWT)**. Below is a minimal implementation; you can swap it for sessions/OIDC later.

**install**  

```bash
npm i jsonwebtoken bcryptjs express-validator
```

**auth middleware (src/middleware/auth.js)**

```js
// src/middleware/auth.js
const jwt = require('jsonwebtoken');

const auth = (req, res, next) => {
  const authHeader = req.headers.authorization;
  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing or invalid Authorization header' });
  }

  const token = authHeader.split(' ')[1];
  try {
    const payload = jwt.verify(token, process.env.JWT_SECRET);
    req.user = payload;               // payload should contain { sub, role, ... }
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Invalid token' });
  }
};

module.exports = auth;
```

**users route (routes/users.js)** – now protected and with minimal validation.

```js
// routes/users.js
const express = require('express');
const router = express.Router();
const auth = require('../middleware/auth');
const { body, param, validationResult } = require('express-validator');

// Mock DB – replace with real DB calls
const USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com', role: 'admin' },
  { id: 2, name: 'Bob',   email: 'bob@example.com',   role: 'user' }
];

/* GET /users – only authenticated users can list, and we hide PII unless role=admin */
router.get('/', auth, (req, res) => {
  const sanitized = USERS.map(u => ({
    id: u.id,
    name: u.name,
    // only admins may see email
    ...(req.user.role === 'admin' ? { email: u.email } : {})
  }));
  res.json(sanitized);
});

/* Example POST /users – demonstrates input validation & password hashing */
router.post(
  '/',
  auth,
  [
    body('name').isString().trim().isLength({ min: 1, max: 100 }),
    body('email').isEmail().normalizeEmail(),
    body('password').isStrongPassword()
  ],
  async (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) return res.status(400).json({ errors: errors.array() });

    const { name, email, password } = req.body;
    const bcrypt = require('bcryptjs');
    const hash = await bcrypt.hash(password, 12);

    // Insert into DB using a parameterised query (example with pg)
    // await db.query('INSERT INTO users (name,email,password) VALUES ($1,$2,$3)', [name,email,hash]);

    res.status(201).json({ message: 'User created' });
  }
);

module.exports = router;
```

**Key points**

* **Authentication** – every protected route checks a signed JWT (`auth` middleware).  
* **Authorization** – we hide e‑mail unless the supplied JWT contains `role: 'admin'`. You can expand this to fine‑grained RBAC.  
* **Input validation** – `express-validator` sanitises and validates all incoming fields, protecting against injection and malformed data.  
* **Password handling** – bcrypt with a cost factor (`12`) prevents credential stuffing and stores only a hash.

