## 1️⃣ AWS Secrets Manager (or Parameter Store)

**Install the SDK**

```bash
npm i aws-sdk
```

**Create a tiny helper (`src/secrets/aws.js`)**

```js
// src/secrets/aws.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });

/**
 * Fetch a secret JSON string from AWS Secrets Manager.
 *   - secretName: the full ARN or name of the secret.
 *   - fallbackKey: optional environment variable name to use if the secret cannot be fetched.
 */
async function loadSecret(secretName, fallbackKey) {
  try {
    const data = await client.send(new GetSecretValueCommand({ SecretId: secretName }));
    const secretString = data.SecretString;               // Secret stored as plain JSON string
    const parsed = JSON.parse(secretString);

    // Populate process.env for the rest of the app
    Object.entries(parsed).forEach(([k, v]) => {
      if (!process.env[k]) process.env[k] = v;
    });
    console.info(`✅ Loaded secret "${secretName}"`);
  } catch (err) {
    console.warn(`⚠️ Could not load secret "${secretName}" – using fallback env var ${fallbackKey}`);
    if (fallbackKey && process.env[fallbackKey]) {
      // already set in the local environment (e.g., .env)
    } else {
      throw err; // fail fast in CI / prod
    }
  }
}

module.exports = { loadSecret };
```

**Wire it into the start‑up (e.g., `server.js`)**

```js
// server.js
require('dotenv').config();                 // local dev .env (optional)
const { loadSecret } = require('./src/secrets/aws');

(async () => {
  // Example secret stored as JSON:
  // {
  //   "DATABASE_URL": "postgres://admin:pw@db.internal:5432/production",
  //   "STRIPE_SECRET_KEY": "sk_live_…"
  // }
  await loadSecret('my-app/prod');         // secret name or ARN
  // Now process.env.DATABASE_URL, STRIPE_SECRET_KEY etc. are populated

  const app = require('./app');
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => console.log(`🚀 Server on ${PORT}`));
})();
```

*Benefits*:

* The secret is **encrypted at rest** in AWS and only decrypted inside the pod/container.
* Rotation can be done in the console without touching the code.
* IAM policies give you fine‑grained access control.

