const client = new SecretManagerServiceClient();

async function loadSecret(name) {
  const [version] = await client.accessSecretVersion({ name });
  const payload = version.payload.data.toString('utf8');

  const secretObj = JSON.parse(payload);
  Object.entries(secretObj).forEach(([k, v]) => {
    if (!process.env[k]) process.env[k] = v;
  });
  console.info(`✅ GCP secret ${name} loaded`);
}

module.exports = { loadSecret };
```

Usage in `server.js` is identical to the AWS example (`await loadSecret('projects/…/secrets/my-app/versions/latest')`).

