```js
// config.js – centralised configuration (new file)
require('dotenv').config();                     // Loads .env *only* in development
const { SecretManagerServiceClient } = require('@google-cloud/secret-manager'); // example for GCP

/**
 * Helper to read a secret from a cloud secret manager.
 * Falls back to an environment variable (useful for local dev).
 *
 * @param {string} name The secret name (e.g., "JWT_SIGNING_KEY")
 * @returns {Promise<string>} The secret value
 */
async function getSecret(name) {
  // 1️⃣ Prefer cloud secret manager if the runtime provides the appropriate env var
  if (process.env.GCP_PROJECT) {
    const client = new SecretManagerServiceClient();
    const [version] = await client.accessSecretVersion({
      name: `projects/${process.env.GCP_PROJECT}/secrets/${name}/versions/latest`,
    });
    return version.payload.data.toString('utf8');
  }

  // 2️⃣ Fallback to plain env var (good for local dev)
  if (process.env[name]) {
    return process.env[name];
  }

  throw new Error(`Secret "${name}" not found`);
}

// Export a promise‑based config object so callers can `await` it
module.exports = {
  port: process.env.PORT || 3000,
  // Example of a secret we might need later
  getJwtKey: () => getSecret('JWT_SIGNING_KEY'), // returns a Promise<string>
};
```

