```

```js
// app.js – hardened version
require('dotenv').config();          // <-- A02: keep secrets out of code
const express = require('express');
const helmet = require('helmet');    // A05 – security headers
const rateLimit = require('express-rate-limit'); // A04/A05 – DoS mitigation
const cors = require('cors');        // A01 – control origins
const morgan = require('morgan');    // A09 – request logging
const app = express();

// ---------- Global Middleware ----------
app.use(helmet());                    // Sets X‑Content-Type-Options, CSP, HSTS, etc.
app.use(cors({                       // Adjust to your client origins
  origin: process.env.ALLOWED_ORIGINS?.split(',') || '*',
  methods: ['GET','POST','PUT','DELETE'],
}));
app.use(express.json());             // parses JSON bodies (future use)
app.use(morgan('combined'));         // structured request logs

// ---------- Rate Limiting ----------
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,          // 15 minutes
  max: 100,                         // max 100 requests per IP
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});
app.use('/users', apiLimiter);       // protect the sensitive endpoint

// ---------- Health endpoint ----------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ---------- Users endpoint (protected) ----------
const AUTH_TOKEN = process.env.API_TOKEN; // simple token auth for demo

function authMiddleware(req, res, next) {
  const token = req.headers.authorization?.replace('Bearer ', '');
  if (!token || token !== AUTH_TOKEN) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  next();
}

// Apply auth + rate‑limit
app.get('/users', authMiddleware, (req, res) => {
  // In a real app you’d fetch from a DB; ensure any DB calls are parameterised.
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// ---------- Centralized Error Handler ----------
app.use((err, req, res, next) => {
  console.error(err); // could be replaced with winston/pino
  const status = err.status || 500;
  const message = process.env.NODE_ENV === 'production'
    ? 'Internal Server Error'
    : err.message;
  res.status(status).json({ error: message });
});

// ---------- Server startup ----------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

