## 4. Refactoring `app.js` to Pull Secrets from a Secrets Manager

> **Assumption** – you have a cloud‑provider‑agnostic or provider‑specific secrets manager already set up (e.g., AWS Secrets Manager, Azure Key Vault, Google Secret Manager, HashiCorp Vault, or a Kubernetes secret). The example shows AWS, but the pattern is the same for any service.

### 4.1. Install the SDK you need
```bash
npm install @aws-sdk/client-secrets-manager   # For AWS
# or
npm install @azure/keyvault-secrets @azure/identity   # Azure
# or
npm install @google-cloud/secret-manager               # GCP
# or
npm install node-vault                                 # HashiCorp Vault
```

### 4.2. Create a small **secrets loader** module (`secrets.js`)

```js
// secrets.js
// ------------------------------
// Centralised secret‑fetching logic.
// Adjust the implementation for your chosen provider.
// ------------------------------

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

// The name (or ARN) of the secret that holds the JWT secret.
// This value can be baked into the image, or supplied via an env var set by the deployment platform.
const JWT_SECRET_NAME = process.env.JWT_SECRET_NAME || 'myapp/jwt-secret';

let cachedJwtSecret = null;

/**
 * Retrieve the JWT secret from AWS Secrets Manager (once, then cache).
 * If the secret cannot be loaded, the process will exit – we never want to start the server without it.
 */
async function loadJwtSecret() {
  if (cachedJwtSecret) return cachedJwtSecret;   // already loaded

  const client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });

  try {
    const command = new GetSecretValueCommand({ SecretId: JWT_SECRET_NAME });
    const response = await client.send(command);

    // Secrets Manager returns either SecretString or SecretBinary
    const secretString = response.SecretString
      ? response.SecretString
      : Buffer.from(response.SecretBinary, 'base64').toString('utf-8');

    // If you store a JSON document, you can parse it:
    // const parsed = JSON.parse(secretString);
    // cachedJwtSecret = parsed.jwtSecret;
    cachedJwtSecret = secretString; // assuming the secret *is* just the raw JWT secret
    console.info('✅ JWT secret successfully loaded from Secrets Manager');
    return cachedJwtSecret;
  } catch (err) {
    console.error('❌ Failed to load JWT secret from Secrets Manager:', err);
    process.exit(1); // Do not start the server insecurely
  }
}

/**
 * Public accessor that returns the secret (await it where needed).
 */
async function getJwtSecret() {
  return await loadJwtSecret();
}

module.exports = { getJwtSecret };
```

