  require('dotenv').config({ path: '.env' });
}

// Helper to conditionally load from a secret manager
async function loadProductionSecrets() {
  if (process.env.NODE_ENV !== 'production') return;

  // ---- Example for AWS Secrets Manager -----------------
  const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
  const client = new SecretsManagerClient({ region: process.env.AWS_REGION });

  // Adjust secret names to match your infrastructure
  const secretNames = {
    db:    'myapp/database',
    stripe: 'myapp/stripe',
    anthropic: 'myapp/anthropic',
  };

  for (const [key, name] of Object.entries(secretNames)) {
    const { SecretString } = await client.send(new GetSecretValueCommand({ SecretId: name }));
    const secretObj = JSON.parse(SecretString);
    // Populate process.env with each key/value (or expose via a Config object)
    Object.assign(process.env, secretObj);
  }
}

// Export a promise that resolves when everything is ready
module.exports = (async () => {
  await loadProductionSecrets();

  // Now expose a typed config object (helps with IDE autocomplete)
  return {
    port:               process.env.PORT || 3000,
    nodeEnv:            process.env.NODE_ENV || 'development',
    databaseUrl:        process.env.DATABASE_URL,
    stripeSecretKey:    process.env.STRIPE_SECRET_KEY,
    anthropicApiKey:    process.env.ANTHROPIC_API_KEY,
    awsAccessKeyId:     process.env.AWS_ACCESS_KEY_ID,
    awsSecretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
    logfireToken:       process.env.LOGFIRE_TOKEN,
    // add more as needed …
  };
})();
```

