### 1. Add Security‑Focused Middleware

```js
// app.js (top of the file, after `const app = express();`)

const helmet = require('helmet');          // Sets secure HTTP headers
const cors = require('cors');              // Controls cross‑origin requests
const rateLimit = require('express-rate-limit'); // Throttles abusive traffic
const xssClean = require('xss-clean');     // Basic XSS sanitisation for query/body strings
const hpp = require('hpp');                // HTTP Parameter Pollution protection

// 1️⃣ Helmet – all default protections + CSP (Content‑Security‑Policy)
app.use(
  helmet({
    contentSecurityPolicy: {
      directives: {
        defaultSrc: ["'self'"],
        scriptSrc: ["'self'"],
        objectSrc: ["'none'"],
        upgradeInsecureRequests: [],
      },
    },
  })
);

// 2️⃣ CORS – restrict origins to those you actually serve (example: same domain)
app.use(
  cors({
    origin: process.env.ALLOWED_ORIGINS?.split(',') || 'http://localhost:3000',
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
    credentials: true,
  })
);

// 3️⃣ Rate limiting – prevents brute‑force, DoS, and enumeration attacks
const limiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: 100,            // max 100 requests per IP per minute
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// 4️⃣ XSS & HPP protection (even if we currently have no body parsing)
app.use(xssClean());
app.use(hpp());

// 5️⃣ JSON body parser (if you later add POST/PUT routes)
app.use(express.json());
```

