### 3️⃣ Pull **real secrets** from a dedicated secrets manager

Below are three common patterns (pick the one that matches your cloud provider). All of them **retrieve secrets at runtime**, never store them in source control or in the container image.

#### a) AWS Secrets Manager (Node.js)

```bash
npm i @aws-sdk/client-secrets-manager
```

```js
// secrets.js – thin wrapper
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const client = new SecretsManagerClient({ region: process.env.AWS_REGION });

/**
 * Retrieves a secret as a plain string.
 * Caches the value for the life of the process (optional).
 */
let cache = {};

async function getSecret(name) {
  if (cache[name]) return cache[name];

  const cmd = new GetSecretValueCommand({ SecretId: name });
  const resp = await client.send(cmd);
  const secretString = resp.SecretString; // assume string, you can JSON.parse if needed
  cache[name] = secretString;
  return secretString;
}

module.exports = { getSecret };
```

```js
// In app.js (or a config module)
const { getSecret } = require('./secrets');

(async () => {
  // Example: JWT secret and DB connection string
  const JWT_SECRET = await getSecret('myapp/jwt-secret');
  const DATABASE_URL = await getSecret('myapp/database-url');

  // make them globally available (or inject via DI)
  process.env.JWT_SECRET = JWT_SECRET;
  process.env.DATABASE_URL = DATABASE_URL;

  // start the server **after** secrets are loaded
  startServer();
})();
```

#### b) Google Cloud Secret Manager

```bash
npm i @google-cloud/secret-manager
```

```js
const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');
const client = new SecretManagerServiceClient();

async function getSecret(name) {
  const [version] = await client.accessSecretVersion({
    name: `projects/${process.env.GCP_PROJECT}/secrets/${name}/versions/latest`,
  });
  return version.payload.data.toString('utf8');
}
```

#### c) HashiCorp Vault (generic HTTP API)

```bash
npm i node-vault
```

```js
const vault = require('node-vault')({ endpoint: process.env.VAULT_ADDR, token: process.env.VAULT_TOKEN });

async function getSecret(path) {
  const result = await vault.read(path);
  return result.data;
}
```

**Common pattern:**  
*Wrap the secret‑fetching in a small async utility (`getSecret`) and **await it before you start the server**.* This guarantees the app never runs with missing or default secrets.

