// app.js – Secure, production‑ready Express starter
// ------------------------------------------------
// This file demonstrates common OWASP‑Top‑10 mitigations for a simple
// Node/Express service.  It keeps the original /health and /users routes
// but adds security hardening, authentication, rate‑limiting, CORS,
// input validation, and safe error handling.

'use strict';

// ──────────────────────────────────────────────────────────────────────
// 1️⃣  Imports & Constants
// ──────────────────────────────────────────────────────────────────────
const express = require('express');
const helmet = require('helmet');                         // security headers
const cors = require('cors');                             // CORS control
const rateLimit = require('express-rate-limit');         // DoS protection
const morgan = require('morgan');                         // request logging
const { body, param, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');                     // simple JWT auth (demo)
require('dotenv').config();                               // env vars

const app = express();

// ──────────────────────────────────────────────────────────────────────
// 2️⃣  Global Middleware
// ──────────────────────────────────────────────────────────────────────
// Hide the default Express header
app.disable('x-powered-by');

// Helmet adds a collection of security‑related HTTP headers
app.use(helmet());

// Basic request logging (replace with Winston/elastic in prod)
app.use(morgan('combined'));

// JSON body parser (needed before validation)
app.use(express.json());

// CORS – only allow trusted origins (adjust the list to your UI domains)
const corsOptions = {
  origin: (origin, callback) => {
    const whitelist = [
      'https://my-frontend.example.com',
      // add more allowed origins here
    ];
    if (!origin || whitelist.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
};
app.use(cors(corsOptions));

// Rate limiting – 100 requests per 15‑minute window per IP (tune as needed)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true, // Return RateLimit headers
  legacyHeaders: false,
});
app.use(limiter);

// ──────────────────────────────────────────────────────────────────────
// 3️⃣  Simple JWT Authentication Middleware (demo)
// ──────────────────────────────────────────────────────────────────────
// In a real app you'd have a proper user store & refresh‑token flow.
const authenticateJWT = (req, res, next) => {
  const authHeader = req.headers.authorization;
  if (!authHeader) return res.status(401).json({ error: 'Missing Authorization header' });

  const token = authHeader.split(' ')[1]; // Expect "Bearer <token>"
  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: 'Invalid or expired token' });
    req.user = user; // attach decoded payload for later use
    next();
  });
};

// ──────────────────────────────────────────────────────────────────────
// 4️⃣  Routes
// ──────────────────────────────────────────────────────────────────────

// Health‑check – public, no auth needed
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Mock user data – in a real app query a DB with proper ACLs.
const USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com'   },
];

// /users – now protected by JWT auth and returns only non‑PII by default.
// Clients can request extra fields via a query param after proper validation.
app.get(
  '/users',
  authenticateJWT,
  // OPTIONAL: Validate query param "includeEmail"
  (req, res, next) => {
    const includeEmail = req.query.includeEmail === 'true';
    // Basic validation – reject anything else
    if (req.query.includeEmail && !includeEmail) {
      return res.status(400).json({ error: 'Invalid includeEmail value' });
    }
    req.includeEmail = includeEmail;
    next();
  },
  (req, res) => {
    const result = USERS.map(u => ({
      id: u.id,
      name: u.name,
      ...(req.includeEmail && { email: u.email }) // expose only if requested
    }));
    res.json(result);
  }
);

// Example POST endpoint demonstrating input validation & sanitisation
app.post(
  '/register',
  [
    body('name')
      .trim()
      .isLength({ min: 2, max: 50 })
      .withMessage('Name must be between 2 and 50 characters'),
    body('email')
      .isEmail()
      .normalizeEmail()
      .withMessage('A valid e‑mail address is required')
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(422).json({ errors: errors.array() });
    }

    // At this point the inputs are safe to use (e.g., insert into DB)
    const { name, email } = req.body;
    // ... create user, send verification, etc.
    res.status(201).json({ message: 'User created', user: { name, email } });
  }
);

// ──────────────────────────────────────────────────────────────────────
// 5️⃣  Global Error Handler
// ──────────────────────────────────────────────────────────────────────
app.use((err, req, res, next) => {
  // If the error is already an HTTP error, keep its status
  const status = err.status || 500;
  // Never leak stack traces in production
  const response = {
    error: err.message || 'Internal Server Error',
  };
  if (process.env.NODE_ENV !== 'production') {
    response.stack = err.stack;
  }
  res.status(status).json(response);
});

// ──────────────────────────────────────────────────────────────────────
// 6️⃣  Server Startup
// ──────────────────────────────────────────────────────────────────────
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`🔒 Secure Express server running on port ${PORT}`);
});

module.exports = app;
```

### What the new code adds (and why it matters)

| Feature | OWASP Top‑10 Mapping | Why it matters |
|---------|----------------------|----------------|
| **Helmet** (security headers) | A5 – Security Misconfiguration, A7 – XSS | Prevents click‑jacking (`X‑Frame‑Options`), MIME sniffing, XSS (`X‑Content‑Type‑Options`, CSP), etc. |
| **CORS whitelist** | A5 – Misconfiguration | Stops browsers from allowing malicious origins to call your API. |
| **Rate limiting** | A5 – DoS, A10 – Insufficient Logging | Throttles abusive clients, reduces brute‑force surface. |
| **JWT auth middleware** | A2 – Broken Authentication | Protects sensitive `/users` data from anonymous access. |
| **Reduced data exposure** | A3 – Sensitive Data Exposure | Email addresses are only returned when the caller explicitly asks (and is authenticated). |
| **Input validation (`express-validator`)** | A1 – Injection, A4 – XML External Entity (if XML used), A9 – Using Components with Known Vulnerabilities | Guarantees only expected, sanitized input reaches business logic or DB. |
| **Hide `X-Powered-By`** | A5 – Misconfiguration | Removes the banner that identifies the framework/version. |
| **Central error handler** | A10 – Insufficient Logging & Monitoring | Uniform error responses; no stack‑trace leakage in prod. |
| **Request logging (morgan)** | A10 – Logging | Enables detection of abnormal request patterns. |
| **Environment‑based config (`dotenv`)** | A5 – Misconfiguration | Secrets (e.g., JWT secret) never hard‑coded. |
| **Dependency hygiene reminder** | A9 – Vulnerable Components | Run `npm audit` / `npx snyk test` regularly. |

