#### 2️⃣ Create a small “secrets loader” module

*File:* `config/secrets.js`

```js
// config/secrets.js
/**
 * Centralised secret‑loading logic.
 *
 * - In development we read a .env file (if present) via dotenv.
 * - In production we expect the variables to be injected by the platform.
 * - For high‑value secrets we optionally pull them from a cloud provider
 *   using its SDK (example shown for AWS Secrets Manager).
 */
const fs = require('fs');
const path = require('path');

function loadEnvIfPresent() {
  const envPath = path.resolve(process.cwd(), '.env');
  if (fs.existsSync(envPath)) {
    // Load only when the file exists – safe for prod where .env is omitted
    require('dotenv').config({ path: envPath });
    console.info('🔑 Loaded environment variables from .env');
  }
}

/**
 * Helper to read a secret value with a clear error when missing.
 */
function getSecret(name) {
  const value = process.env[name];
  if (!value) {
    throw new Error(`Missing required environment variable "${name}"`);
  }
  return value;
}

/**
 * Example: fetch a secret from AWS Secrets Manager (optional).
 * Replace with your provider as needed.
 */
async function fetchAwsSecret(secretId, region = 'us-east-1') {
  const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
  const client = new SecretsManagerClient({ region });
  const data = await client.send(new GetSecretValueCommand({ SecretId: secretId }));
  return data.SecretString;
}

// Execute the dev‑only loader *once* at module import
loadEnvIfPresent();

module.exports = {
  getSecret,
  fetchAwsSecret,
};
```

> **Why this helps**  
> *All secret accesses go through `getSecret()` → a missing variable immediately aborts start‑up, preventing the app from running with default or empty credentials.*  
> *The AWS fetch example shows how you can replace a static env var with a runtime secrets‑manager call, keeping the secret out of the host filesystem.*

#### 3️⃣ Use the loader in `app.js`

