### 3.2 Centralised security & configuration setup  

```js
// ---------- app.js (top) ----------
require('dotenv').config();               // loads .env file
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const jwt = require('jsonwebtoken');      // for auth
const { body, param, query, validationResult } = require('express-validator');

const app = express();

// ---------- Security middleware ----------
app.use(helmet());                         // Sets many secure headers
app.use(cors({                             // Adjust origins for production
  origin: process.env.CORS_ORIGIN?.split(',') || '*',
  methods: ['GET','POST','PUT','DELETE'],
}));
app.use(express.json());                  // Parse JSON bodies safely
app.use(morgan('combined'));               // Logs every request (can pipe to file/ELK)

// ---------- Rate limiting ----------
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                // limit each IP to 100 requests per window
  standardHeaders: true,  // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false,
});
app.use(limiter);
```

### 3.3 Add a **JWT‑based auth** middleware  

```js
// ---------- Auth middleware ----------
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Expect "Bearer <token>"
  if (!token) return res.status(401).json({ error: 'Missing token' });

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: 'Invalid token' });
    req.user = user; // payload can contain role, id, etc.
    next();
  });
}
```

> **Tip:** Store `JWT_SECRET` in a `.env` file and never commit it.

### 3.4 Protect the `/users` endpoint  

```js
// Only authenticated users can list other users
app.get('/users', authenticateToken, (req, res) => {
  // Example: you might only expose minimal data or filter by role
  const safeUsers = [
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ];
  res.json(safeUsers);
});
```

> **Result:** No unauthenticated access (fixes A01, A07).  Email addresses are no longer exposed (reduces data leakage risk).

