```js
// Example: a POST /users route that creates a user
app.post(
  '/users',
  authenticateToken,
  // validation chain:
  [
    body('name')
      .trim()
      .isLength({ min: 1, max: 100 })
      .withMessage('Name is required and must be <100 chars'),
    body('email')
      .trim()
      .isEmail()
      .normalizeEmail()
      .withMessage('Valid e‑mail required')
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // At this point data is safe to use → insert into DB, etc.
    const { name, email } = req.body;
    // ... persist user ...
    res.status(201).json({ id: 3, name, email });
  }
);
```

> **Result:** Prevents injection attacks (A03) and ensures data integrity (A08).

