    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    const { name, email } = req.body;
    // TODO: persist user safely (e.g., hashed password, DB insert)
    res.status(201).json({ id: 3, name, email });
  }
);

// ---------- Global error handler ----------
app.use((err, req, res, next) => {
  console.error(err);
  const status = err.status || 500;
  res.status(status).json({
    error: status === 500 ? 'Internal Server Error' : err.message,
  });
});

// ---------- HTTPS redirect for production ----------
if (process.env.NODE_ENV === 'production') {
  app.enable('trust proxy');
  app.use((req, res, next) => {
    if (req.secure) return next();
    res.redirect(`https://${req.headers.host}${req.originalUrl}`);
  });
}

// ---------- Server ----------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Server running on port ${PORT}`));

module.exports = app;
```

> **After the patch:**  
> 1. Create a `.env` file with at least `JWT_SECRET` (a strong random string) and optionally `CORS_ORIGIN`.  
> 2. Run `node app.js` (or use a process manager like `pm2` / Docker).  
> 3. Generate a JWT for testing:  

```bash
node -e "console.log(require('jsonwebtoken').sign({sub: 'testUser'}, process.env.JWT_SECRET, {expiresIn: '1h'}))"
```

> 4. Call the protected route:  

```bash
curl -H "Authorization: Bearer <token>" http://localhost:3000/users
```

